select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000001',false);
insert into public.partner_network_partners(id,user_id,code,status,business_name,contact_name,email,phone,region,partner_type)
 values('00000000-0000-4000-8000-000000000801','00000000-0000-4000-8000-000000000003','HL-A','approved','Synthetic A','A','a@example.test','0901000001','Synthetic','sales_rep'),
 ('00000000-0000-4000-8000-000000000802','00000000-0000-4000-8000-000000000004','HL-B','approved','Synthetic B','B','b@example.test','0901000002','Synthetic','sales_rep');
insert into public.partner_network_sales_pages(partner_id,slug,display_name,phone,region,tea_ids,published,created_by,updated_by)
 values('00000000-0000-4000-8000-000000000801','retail-partner-a','Synthetic A','0901000001','Synthetic',array['black-op1'],true,'00000000-0000-4000-8000-000000000001','00000000-0000-4000-8000-000000000001'),
 ('00000000-0000-4000-8000-000000000802','retail-partner-b','Synthetic B','0901000002','Synthetic',array['black-op1'],true,'00000000-0000-4000-8000-000000000001','00000000-0000-4000-8000-000000000001');
set role authenticated;
select public.partner_network_apply_classic('00000000-0000-4000-8000-000000000801','{"expected_version":0,"reason":"Synthetic prospective Classic agreement for B2C integration only"}');
reset role;
set role anon;
select public.test_assert((select count(*)=5 from jsonb_object_keys(public.partner_network_public_retail_partner('retail-partner-a'))),'public retail DTO has only five approved contact fields');
select public.test_assert(not(public.partner_network_public_retail_partner('retail-partner-a') ?|array['partner_id','user_id','email','costs']),'public retail DTO omits private identity and economics');
select public.test_error($$select public.partner_network_retail_receipt('00000000-0000-4000-8000-000000000901',repeat('a',64))$$,'permission denied');
select public.test_error($$select public.submit_partner_retail_order('00000000-0000-4000-8000-000000000901',repeat('a',64),'{}',null)$$,'permission denied');
select public.test_error($$select * from public.partner_network_retail_receipts$$,'permission denied');
reset role;
set role service_role;
select set_config('request.jwt.claim.role','service_role',false);
select public.test_error($$select public.submit_partner_retail_order('00000000-0000-4000-8000-000000000901',repeat('a',64),public.retail_test_input(),'{"slug":"retail-partner-a","revision":1,"consent":false}')$$,'partner_consent_required');
select public.test_error($$select public.submit_partner_retail_order('00000000-0000-4000-8000-000000000901',repeat('a',64),public.retail_test_input(),'{"slug":"retail-partner-a","revision":2,"consent":true}')$$,'retail_partner_unavailable');
select set_config('test.retail_first',(public.submit_partner_retail_order('00000000-0000-4000-8000-000000000901',repeat('a',64),public.retail_test_input(),'{"slug":"retail-partner-a","revision":1,"consent":true}')->>'orderId'),false);
select public.test_assert((public.submit_partner_retail_order('00000000-0000-4000-8000-000000000901',repeat('a',64),public.retail_test_input(),'{"slug":"retail-partner-a","revision":1,"consent":true}')->>'isNew')::boolean=false,'identical checkout retry returns existing durable order');
select public.test_error($$select public.partner_network_retail_receipt('00000000-0000-4000-8000-000000000901',repeat('b',64))$$,'checkout_retry_conflict');
reset role;
select public.test_assert((select count(*)=1 from public.partner_network_retail_receipts),'only one order receipt after retry');
select public.test_assert((select stock_soc_son=999 from public.catalog_products where id='retail-test'),'retry does not deduct inventory twice');
select public.test_assert((select count(*)=1 from public.trade_opportunities where contact_key='0905550001'),'retail intake enters central CRM exactly once');
select public.test_assert((select channel='b2c' and status='pending' and opportunity_id is null and location='Khách bán lẻ' from public.partner_network_referrals where id='00000000-0000-4000-8000-000000000901'),'new source is pending and does not duplicate customer address');
select public.test_assert(not exists(select 1 from public.partner_network_order_links where order_id=current_setting('test.retail_first')),'pending source has no accepted commission/order ownership');
set role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000003',false);
select public.test_assert((public.partner_network_retail_snapshot('00000000-0000-4000-8000-000000000801')->'intakes')='[]','partner does not see pending source order history');
select public.test_error($$select public.partner_network_retail_snapshot('00000000-0000-4000-8000-000000000802')$$,'partner_required');
select public.test_error($$select public.partner_network_resolve_lead('00000000-0000-4000-8000-000000000901','accept','{"reason":"Partner cannot self-approve source"}')$$,'manager_required');
select public.test_assert(public.partner_network_snapshot()->'orders'='[]','shared own snapshot hides pending retail orders');
select public.test_assert((public.partner_network_snapshot()->'referrals'->0->>'channel')='b2c','own lead shows retail channel without internal orders');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000001',false);
select public.test_error($$select public.partner_network_resolve_lead('00000000-0000-4000-8000-000000000901','accept','{}')$$,'duplicate_resolution_required');
select public.partner_network_resolve_lead('00000000-0000-4000-8000-000000000901','accept','{"reason":"Manager checked customer consent and valid retail source"}');
select public.test_assert((select count(*)=1 from public.partner_network_order_links where order_id=current_setting('test.retail_first') and source='retail'),'approval attaches the actual sourced order');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000003',false);
select public.test_assert(jsonb_array_length(public.partner_network_retail_snapshot('00000000-0000-4000-8000-000000000801')->'intakes')=1,'approved source is visible only to its own partner');
select public.test_assert(position('PRIVATE_ADDRESS' in public.partner_network_snapshot()::text)=0 and position('PRIVATE_TAX' in public.partner_network_snapshot()::text)=0 and position('PRIVATE_BUYER_NOTE' in public.partner_network_snapshot()::text)=0,'own portal excludes full address tax and buyer notes');
reset role;
select public.test_assert((public.partner_network_financial(current_setting('test.retail_first'))->>'cancelled')::boolean=false,'accepted source-backed retail can use normal commission ledger');
set role service_role;
select set_config('test.retail_repeat',(public.submit_partner_retail_order('00000000-0000-4000-8000-000000000902',repeat('b',64),public.retail_test_input(),'{"slug":"retail-partner-a","revision":1,"consent":true}')->>'orderId'),false);
select set_config('test.retail_direct',(public.submit_partner_retail_order('00000000-0000-4000-8000-000000000903',repeat('c',64),public.retail_test_input(),null)->>'orderId'),false);
select set_config('test.retail_competing',(public.submit_partner_retail_order('00000000-0000-4000-8000-000000000904',repeat('d',64),public.retail_test_input(),'{"slug":"retail-partner-b","revision":1,"consent":true}')->>'orderId'),false);
reset role;
select public.test_assert((select referral_id='00000000-0000-4000-8000-000000000901' from public.partner_network_order_links where order_id=current_setting('test.retail_repeat')),'explicit consented repeat reuses the accepted relationship for its new order');
select public.test_assert(not exists(select 1 from public.partner_network_order_links where order_id=current_setting('test.retail_direct')),'same phone without referral/consent never auto-attributes a direct order');
select public.test_assert(not exists(select 1 from public.partner_network_order_links where order_id=current_setting('test.retail_competing')),'competing partner source never steals an accepted customer automatically');
select public.test_assert((public.partner_network_financial(current_setting('test.retail_direct'))->>'cancelled')::boolean=true,'orphan retail never becomes commission eligible');
update public.orders set ts=clock_timestamp() where id=current_setting('test.retail_direct');
set role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000001',false);
select public.test_error($$select public.partner_network_resolve_lead('00000000-0000-4000-8000-000000000904','accept','{"reason":"Competing partner cannot steal an attributed customer"}')$$,'opportunity_already_attributed');
select public.test_error(format('select public.partner_network_link_order(%L,%L,''short'')','00000000-0000-4000-8000-000000000901',current_setting('test.retail_direct')),'verified_retail_source_required');
select public.partner_network_link_order('00000000-0000-4000-8000-000000000901',current_setting('test.retail_direct'),'Manager verified direct buyer authorization and source for this order');
select public.test_assert((select source='manual' from public.partner_network_order_links where order_id=current_setting('test.retail_direct')),'offline source requires explicit reasoned manager attribution');
reset role;
select public.test_assert((public.partner_network_financial(current_setting('test.retail_direct'))->>'cancelled')::boolean=false,'verified manual source can use shared financial reconciliation');
update public.partner_network_sales_pages set published=false where slug='retail-partner-a';
set role service_role;
select public.test_assert((public.partner_network_retail_receipt('00000000-0000-4000-8000-000000000901',repeat('a',64))->>'orderId')=current_setting('test.retail_first'),'lost response can recover previous order even after page withdrawal');
select public.test_error($$select public.submit_partner_retail_order('00000000-0000-4000-8000-000000000905',repeat('e',64),public.retail_test_input(),'{"slug":"retail-partner-a","revision":1,"consent":true}')$$,'retail_partner_unavailable');
reset role;
select public.test_assert(public.partner_network_public_retail_partner('retail-partner-a') is null,'withdrawn page disappears from retail landing');
select public.test_assert(not exists(select 1 from public.partner_network_retail_receipts where request_id='00000000-0000-4000-8000-000000000905'),'withdrawn page fails atomically without uncredited fallback order');
